.form-list-page{min-height:calc(100vh - 52px);padding:18px;display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:18px;background:#f7f8fa;color:#172535}.form-list-page main{min-width:0}.page-head{height:72px;display:flex;align-items:flex-start;justify-content:space-between}.page-head h1{margin:2px 0 7px;font-size:22px}.page-head p{margin:0;color:#5f7083;font-size:12px}.card{background:#fff;border:1px solid #e3e8ed;border-radius:6px}.filters{display:grid;grid-template-columns:220px 220px minmax(300px,1fr) auto;gap:16px;align-items:end;padding:18px;margin-bottom:18px}.filters label{display:flex;flex-direction:column;gap:8px;font-size:12px}.filter-actions{display:flex;gap:8px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:18px;margin-bottom:18px}.stats article{height:108px;padding:0 28px;display:flex;align-items:center;gap:28px;background:#fff;border:1px solid #e3e8ed;border-radius:6px}.stats i{font-size:42px}.stats span{display:block;color:#45586d;font-size:14px}.stats b{display:block;margin-top:8px;font-size:28px}.table-card{overflow:hidden}.table-card ::v-deep .el-table th{height:46px;background:#f7f9fb;color:#24364a}.table-card ::v-deep .el-table td{height:52px}.table-card footer{height:64px;padding:0 16px;display:flex;align-items:center;justify-content:space-between;font-size:12px}.rules{align-self:start;margin-top:90px;padding:22px}.rules h2{margin:0 0 24px;font-size:18px}.rules ul{padding-left:19px;margin:0}.rules li{margin-bottom:23px;line-height:1.6;font-size:13px}.blue{color:#247fea}.green{color:#0aa05a}.orange{color:#f18a0b}.gray{color:#8793a1}.danger{color:#e55353!important}@media(max-width:1450px){.form-list-page{grid-template-columns:minmax(0,1fr) 250px;gap:12px;padding:14px}.filters{grid-template-columns:180px 180px minmax(260px,1fr) auto;gap:10px}.stats{gap:10px}.stats article{padding:0 18px;gap:18px}.rules{padding:16px}}@media(max-width:1150px){.form-list-page{grid-template-columns:1fr}.rules{margin-top:0}.filters{grid-template-columns:repeat(2,minmax(180px,1fr))}.filter-actions{align-self:end}.stats{grid-template-columns:repeat(2,1fr)}}@media(max-width:720px){.page-head{height:auto;flex-direction:column;gap:12px;margin-bottom:12px}.filters,.stats{grid-template-columns:1fr}.table-card{overflow-x:auto}.table-card .el-table{min-width:1200px}}
</style>
